"""Core lens: fold records into a schema, check records against it, persist it."""

from __future__ import annotations

import json
import os
from typing import Any, Iterator

SCHEMA_FILE = "schema.json"

TYPE_OBJECT = "object"
TYPE_ARRAY = "array"
TYPE_STRING = "string"
TYPE_NUMBER = "number"
TYPE_BOOLEAN = "boolean"
TYPE_NULL = "null"

VALID_TYPES = {
    TYPE_OBJECT,
    TYPE_ARRAY,
    TYPE_STRING,
    TYPE_NUMBER,
    TYPE_BOOLEAN,
    TYPE_NULL,
}


class SchemaConflict(Exception):
    """Raised when an operation needs a usable stored schema and none exists."""


def value_type(value: Any) -> str:
    """Return the JSON type name of a JSON-compatible Python value."""
    if value is None:
        return TYPE_NULL
    # bool is a subclass of int: check it first.
    if isinstance(value, bool):
        return TYPE_BOOLEAN
    if isinstance(value, (int, float)):
        return TYPE_NUMBER
    if isinstance(value, str):
        return TYPE_STRING
    if isinstance(value, list):
        return TYPE_ARRAY
    if isinstance(value, dict):
        return TYPE_OBJECT
    raise TypeError(f"value is not JSON compatible: {type(value).__name__}")


def _new_node() -> dict:
    return {
        "type": set(),
        "fields": {},
        "items": None,
        "count": 0,
        "record_count": 0,
    }


def _fold(node: dict, value: Any) -> None:
    """Fold one value into a schema node, merging by type/name."""
    kind = value_type(value)
    node["type"].add(kind)

    if kind == TYPE_OBJECT:
        node["count"] += 1
        node["record_count"] += 1
        for name, item in value.items():
            field = node["fields"].get(name)
            if field is None:
                field = _new_node()
                node["fields"][name] = field
            field["count"] += 1
            _fold(field, item)
    elif kind == TYPE_ARRAY:
        if node["items"] is None:
            node["items"] = _new_node()
        for item in value:
            _fold(node["items"], item)
    else:
        node["count"] += 1


def _check(node: dict, value: Any, path: str, issues: list[str]) -> None:
    """Append every mismatch between value and node to issues."""
    kind = value_type(value)
    if kind not in node["type"]:
        issues.append(
            f"{path}: type {kind} not in observed types {sorted(node['type'])}"
        )
        return

    if kind == TYPE_OBJECT:
        for name in node["fields"]:
            field = node["fields"][name]
            if name not in value and not field["optional"]:
                child = f"{path}.{name}" if path else name
                issues.append(f"{child}: required field missing")
        for name, item in value.items():
            child = f"{path}.{name}" if path else name
            field = node["fields"].get(name)
            if field is None:
                issues.append(f"{child}: field not in schema")
            else:
                _check(field, item, child, issues)
    elif kind == TYPE_ARRAY:
        items = node["items"]
        child_prefix = f"{path}[]"
        for item in value:
            _check(items, item, child_prefix, issues)


def _to_jsonable(node: dict) -> dict:
    data: dict = {"type": sorted(node["type"])}
    if TYPE_OBJECT in node["type"]:
        data["count"] = node["count"]
        data["record_count"] = node["record_count"]
        data["fields"] = {
            name: _field_to_jsonable(field) for name, field in sorted(node["fields"].items())
        }
    if TYPE_ARRAY in node["type"]:
        data["items"] = _to_jsonable(node["items"]) if node["items"] is not None else None
    if node["type"] <= {TYPE_STRING, TYPE_NUMBER, TYPE_BOOLEAN, TYPE_NULL} and node["type"]:
        data["count"] = node["count"]
    return data


def _field_to_jsonable(field: dict) -> dict:
    data = _to_jsonable(field)
    data["count"] = field["count"]
    data["optional"] = _is_optional(field)
    return data


def _is_optional(field: dict) -> bool:
    parent = field.get("_parent_record_count")
    return bool(parent is not None and field["count"] < parent)


def _from_dict(data: Any) -> dict:
    """Rebuild a node from persisted data, raising SchemaConflict if corrupt."""
    if not isinstance(data, dict):
        raise SchemaConflict("schema node must be an object")
    types = data.get("type")
    if not isinstance(types, list) or not types:
        raise SchemaConflict("schema node is missing its observed types")
    type_set = set(types)
    if not type_set <= VALID_TYPES or len(type_set) != len(types):
        raise SchemaConflict(f"invalid type list in schema: {types!r}")

    node = _new_node()
    node["type"] = type_set

    if TYPE_OBJECT in type_set:
        fields = data.get("fields")
        if not isinstance(fields, dict):
            raise SchemaConflict("object node is missing its fields map")
        record_count = data.get("record_count")
        if not isinstance(record_count, int) or record_count < 0:
            raise SchemaConflict("object node has an invalid record_count")
        node["record_count"] = record_count
        node["count"] = record_count
        for name, raw in fields.items():
            child = _field_from_dict(raw, record_count)
            node["fields"][name] = child
    if TYPE_ARRAY in type_set:
        items = data.get("items")
        if items is None:
            node["items"] = None
        else:
            node["items"] = _from_dict(items)
    if type_set <= {TYPE_STRING, TYPE_NUMBER, TYPE_BOOLEAN, TYPE_NULL}:
        count = data.get("count")
        if not isinstance(count, int) or count < 0:
            raise SchemaConflict("value node has an invalid count")
        node["count"] = count
    return node


def _field_from_dict(data: Any, parent_record_count: int) -> dict:
    node = _from_dict(data)
    count = data.get("count")
    optional = data.get("optional")
    if not isinstance(count, int) or count < 0:
        raise SchemaConflict("field has an invalid observation count")
    if not isinstance(optional, bool):
        raise SchemaConflict("field is missing its optional flag")
    node["count"] = count
    node["optional"] = optional
    expected_optional = count < parent_record_count
    if optional != expected_optional:
        raise SchemaConflict(
            f"field optional flag disagrees with its counts ({count} of {parent_record_count})"
        )
    return node


class Lens:
    """A lens directory holding one inferred schema."""

    def __init__(self, path: str):
        self.path = path
        self._root: dict | None = None

    @property
    def schema_path(self) -> str:
        return os.path.join(self.path, SCHEMA_FILE)

    # -- inference ---------------------------------------------------------

    def infer(self, records: Iterator[dict] | list[dict]) -> dict:
        """Fold a sequence of records into the stored schema and return it."""
        if self._root is None:
            self._root = _new_node()
        for record in records:
            _fold(self._root, record)
        return self.schema()

    # -- checking ----------------------------------------------------------

    def check(self, record: dict) -> list[str]:
        """Report every way one record departs from the stored schema."""
        root = self._require_schema()
        issues: list[str] = []
        _check(root, record, "", issues)
        return issues

    # -- reading -----------------------------------------------------------

    def schema(self) -> dict:
        """Return the stored schema as a JSON-compatible dict."""
        root = self._require_schema()
        return _to_jsonable(root)

    def stats(self) -> dict:
        """Report fields, optional fields, observed types and observation counts."""
        root = self._require_schema()
        fields: list[str] = []
        optional: list[str] = []
        types: dict[str, list[str]] = {}
        counts: dict[str, int] = {}
        _collect_stats(root, "", fields, optional, types, counts)
        return {
            "field_count": len(fields),
            "fields": fields,
            "optional_fields": optional,
            "types": types,
            "counts": counts,
        }

    # -- persistence -------------------------------------------------------

    def save(self) -> None:
        """Persist the stored schema into the lens directory."""
        self._require_schema()
        os.makedirs(self.path, exist_ok=True)
        payload = json.dumps(self.schema(), indent=2, sort_keys=True) + "\n"
        tmp_path = self.schema_path + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as handle:
            handle.write(payload)
        os.replace(tmp_path, self.schema_path)

    def load(self) -> None:
        """Re-read the persisted schema, replacing the in-memory schema wholesale."""
        try:
            with open(self.schema_path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, json.JSONDecodeError) as exc:
            raise SchemaConflict(f"cannot read schema {self.schema_path}: {exc}") from exc
        # Fully rebuild before replacing, so a corrupt file leaves memory intact.
        root = _from_dict(data)
        self._root = root

    # -- internals ---------------------------------------------------------

    def _require_schema(self) -> dict:
        if self._root is None:
            raise SchemaConflict("no schema has been inferred or loaded yet")
        return self._root


def _collect_stats(
    node: dict,
    prefix: str,
    fields: list[str],
    optional: list[str],
    types: dict[str, list[str]],
    counts: dict[str, int],
) -> None:
    for name, field in node["fields"].items():
        path = f"{prefix}.{name}" if prefix else name
        fields.append(path)
        types[path] = sorted(field["type"])
        counts[path] = field["count"]
        if _field_is_optional(field, node["record_count"]):
            optional.append(path)
        _collect_stats(field, path, fields, optional, types, counts)
    if node["items"] is not None:
        _collect_stats(
            node["items"], f"{prefix}[]" if prefix else "[]",
            fields, optional, types, counts,
        )


def _field_is_optional(field: dict, parent_record_count: int) -> bool:
    return field["count"] < parent_record_count

